OptionNotNat.lean.source:
def priceOf (item : String) : Option Nat :=
  if item == "tea" then some 3 else none

def total : Nat := priceOf "tea" + 1

UnknownProtocol.leanfm.source:
import LeanFM.Session.Syntax

protocol Checkout (Client, Shop) {
  q: Quote from Shop to Client;
  Pay from Client to Shop cause q;
}

requirements {
  "Checkout as written" => Checkout;
  "Refunds are answered" => Refund ⊨ (AG (implies (after Ask) (AF (after Refunded))));
}

WhereTypo.leanfm.source:
import LeanFM.Session.Syntax

structure Quote where
  price : Nat
structure Pay where
  amount : Nat

protocol Checkout (Client, Shop) {
  q: Quote from Shop to Client;
  p: Pay from Client to Shop cause q where p.amont = q.price;
}
